// Some portions generated by Co-Pilot
import { fireEvent, render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { axe } from "vitest-axe";
import KeyInitiatives from "../index";

const initiatives = [
  {
    header: "Enhanced Security",
    image: "security.svg",
    description: "Independent security testing.",
  },
  {
    header: "Community",
    image: "community.svg",
    description: (
      <ul>
        <li>Collaborate with other members.</li>
      </ul>
    ),
  },
];

describe("KeyInitiatives", () => {
  it("renders the shared section heading and descriptive content", () => {
    render(
      <KeyInitiatives
        initiatives={initiatives}
        title="How your support helps"
        description="Support open Java."
      />,
    );
    expect(
      screen.getByRole("heading", { level: 2, name: "How your support helps" }),
    ).toBeVisible();
    expect(screen.getByText("Support open Java.")).toBeVisible();
    expect(screen.getAllByRole("heading", { level: 3 })).toHaveLength(2);
  });

  it("uses native disclosures instead of hover-only content and hidden checkboxes", () => {
    const { container } = render(
      <KeyInitiatives initiatives={initiatives} title="Initiatives" />,
    );
    const disclosures = container.querySelectorAll("details");
    expect(disclosures).toHaveLength(2);
    expect(
      container.querySelector('input[type="checkbox"]'),
    ).not.toBeInTheDocument();
    const first = disclosures[0];
    expect(first).not.toHaveAttribute("open");
    fireEvent.click(first.querySelector("summary")!);
    expect(first).toHaveAttribute("open");
    expect(screen.getByText("Independent security testing.")).toBeVisible();
  });

  it("keeps rich content available when a card is expanded", () => {
    const { container } = render(
      <KeyInitiatives initiatives={initiatives} title="Initiatives" />,
    );
    fireEvent.click(container.querySelectorAll("summary")[1]);
    expect(screen.getByRole("listitem")).toHaveTextContent(
      "Collaborate with other members.",
    );
  });

  it("does not create duplicate toggle IDs across component instances", () => {
    const { container } = render(
      <>
        <KeyInitiatives initiatives={initiatives} title="First" />
        <KeyInitiatives initiatives={initiatives} title="Second" />
      </>,
    );
    const ids = Array.from(container.querySelectorAll("[id]")).map(
      (element) => element.id,
    );
    expect(new Set(ids).size).toBe(ids.length);
  });

  it("has no accessibility violations", async () => {
    const { container } = render(
      <KeyInitiatives initiatives={initiatives} title="Initiatives" />,
    );
    expect(await axe(container)).toHaveNoViolations();
  });
});
